
const languageNames={
 ja:'日本語',en:'English',fr:'Français',sv:'Svenska',zh:'中文',ko:'한국어',my:'မြန်မာဘာသာ',id:'Bahasa Indonesia',th:'ไทย'
};

function showPage(id){
  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
  const target=document.getElementById(id);
  if(target) target.classList.add('active');
  document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===id));
  const iphoneEmergency=document.querySelector('.iphone-featured-below-translate');
  if(iphoneEmergency) iphoneEmergency.classList.toggle('v158-hidden', id!=='home');
  window.scrollTo({top:0,behavior:'smooth'});
}
document.querySelectorAll('nav button[data-page]').forEach(btn=>{
  btn.addEventListener('click',()=>showPage(btn.dataset.page));
});

function openLesson(n){ showPage('lesson'+n); }

function demoMessage(){
  document.getElementById('demoResult').textContent='ボタンが動きました！';
}
document.getElementById('demoBtn').addEventListener('click', demoMessage);

let completed=[];
try { const saved=JSON.parse(localStorage.getItem('zeroKaraCompleted')||'[]'); if(Array.isArray(saved)) completed=saved; } catch(e) {}
function completeLesson(n){
  if(!completed.includes(n)) completed.push(n);
  try { localStorage.setItem('zeroKaraCompleted',JSON.stringify(completed)); } catch(e) {}
  updateProgress();
  alert('第'+n+'回を完了にしました。');
}
function updateProgress(){
  const count=[1,2].filter(n=>completed.includes(n)).length;
  const pct=count/2*100;
  document.getElementById('progressBar').style.width=pct+'%';
  document.getElementById('progressText').textContent=count+' / 2 回 完了';
  document.getElementById('badge1').style.opacity=count>=1?'1':'.35';
  document.getElementById('badge2').style.opacity=count>=2?'1':'.35';
}
updateProgress();

function answerQuiz(ans){
  document.getElementById('quizResult').textContent =
    ans==='HTML' ? '正解です。HTMLがページの骨組みを作ります。' : 'もう一度。見た目はCSS、動きはJavaScriptです。';
}

const termDefs={
 HTML:'ホームページの骨組みを作る言語です。',
 CSS:'色・文字・大きさ・配置など、ホームページの見た目を整えます。',
 JavaScript:'ボタン、計算、画面切替など、ホームページに動きを付けます。'
};
function showTerm(name){
  document.getElementById('termTitle').textContent=name;
  document.getElementById('termBody').textContent=termDefs[name]||'用語集で確認してください。';
  document.getElementById('termDialog').showModal();
}

