 const japanese=document.createElement('strong');japanese.textContent=item.name;japanese.dataset.label='japanese';
 const english=document.createElement('strong');english.textContent=glossaryEnglishNames[index];english.dataset.label='english';english.className='notranslate';english.setAttribute('translate','no');english.hidden=true;
 const reading=document.createElement('span');reading.textContent=item.reading;reading.dataset.label='reading';
 b.append(japanese,english,reading);b.addEventListener('click',()=>chooseGlossaryTerm(index));document.getElementById('glossaryCandidates').append(b);return b;
