function glossaryMatchIndices(mode,kana,letter,search,category){
 const query=normalizeGlossary(search).trim().split(/\s+/).filter(Boolean);
 return glossaryItems.map((item,index)=>({item,index})).filter(({item,index})=>{
  if(category&&item.category!==category)return false;
  if(mode==='kana')return !kana||kanaInitial(item.reading)===kana;
  if(mode==='alpha')return !letter||glossaryEnglishInitial(glossaryEnglishNames[index])===letter;
  return query.every(word=>[item.name,item.reading,glossaryEnglishNames[index]].some(text=>normalizeGlossary(text).startsWith(word)||compactGlossary(text).startsWith(compactGlossary(word))));
 }).sort((a,b)=>{
  const first=mode==='alpha'?glossaryEnglishNames[a.index]:normalizeGlossary(a.item.reading);
  const second=mode==='alpha'?glossaryEnglishNames[b.index]:normalizeGlossary(b.item.reading);
  return first.localeCompare(second,mode==='alpha'?'en':'ja')||a.index-b.index;
 }).map(entry=>entry.index);
}
function filterGlossary(){
 const indices=glossaryMatchIndices(glossaryMode,glossaryKana,glossaryLetter,document.getElementById('glossarySearch').value,document.getElementById('glossaryCategory').value);
 const candidates=document.getElementById('glossaryCandidates');
 glossaryCards.forEach(b=>{b.hidden=true;b.setAttribute('aria-pressed','false');b.querySelector('[data-label="japanese"]').hidden=glossaryMode==='alpha'||glossaryUiLanguage==='en';b.querySelector('[data-label="english"]').hidden=glossaryMode!=='alpha'&&glossaryUiLanguage!=='en';});
 indices.forEach(index=>{const b=glossaryCards[index];b.hidden=false;candidates.append(b);});
 document.getElementById('glossaryCount').textContent=indices.length+' / '+glossaryItems.length;
 document.getElementById('glossaryEmpty').hidden=indices.length!==0;
 document.getElementById('glossarySelectionHelp').hidden=indices.length===0;
 document.querySelectorAll('#glossaryKanaGrid button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.kana===glossaryKana)));
 document.querySelectorAll('#glossaryAlphaGrid button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.letter===glossaryLetter)));
}
function setGlossaryMode(mode){
 glossaryMode=mode;glossaryKana='';glossaryLetter='';
 document.getElementById('glossarySearch').value='';
 document.getElementById('glossaryNamePanel').hidden=mode!=='name';
 document.getElementById('glossaryKanaPanel').hidden=mode!=='kana';
 glossaryAlphaPanel.hidden=mode!=='alpha';
 document.getElementById('glossaryLookupLayout').classList.toggle('kana-layout',mode==='kana');
 [['glossaryNameMode','name'],['glossaryKanaMode','kana'],['glossaryAlphaMode','alpha']].forEach(([id,value])=>{
  const b=document.getElementById(id);b.setAttribute('aria-pressed',String(value===mode));b.className=value===mode?'btn':'btn secondary';
 });
 filterGlossary();
}
