const desktopStatus=document.createElement('p');desktopStatus.id='desktopLangStatus';desktopStatus.setAttribute('role','status');desktopStatus.setAttribute('aria-live','polite');desktopTranslateButton.parentElement.after(desktopStatus);
let translationRequest=0, translationLoader=null, appliedLanguage='ja';
function setTranslationStatus(message){translationStatus.textContent=message;desktopStatus.textContent=message;}
function currentPageId(){return document.querySelector('.page.active')?.id||'home';}
function rememberTranslationState(lang){try{sessionStorage.setItem('kazuTranslatePage',currentPageId());sessionStorage.setItem('kazuTranslateLang',lang);}catch(e){}}
function clearGoogTransCookie(){
 const parts=location.hostname.split('.');
 const paths=new Set(['/']);const segments=location.pathname.split('/');
 for(let i=1;i<segments.length;i++)paths.add(segments.slice(0,i).join('/')||'/');
 paths.forEach(path=>{const expired='googtrans=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path='+path;document.cookie=expired;for(let i=0;i<parts.length-1;i++)document.cookie=expired+';domain=.'+parts.slice(i).join('.');});
}
function setGoogTransCookie(target){
 const value='/ja/'+target;
 const host=location.hostname;
 document.cookie='googtrans='+value+';path=/;SameSite=Lax';
 if(host&&host.includes('.'))document.cookie='googtrans='+value+';path=/;domain=.'+host+';SameSite=Lax';
}
function googleTranslateElementInit(){
 if(document.querySelector('select.goog-te-combo'))return;
 try{new google.translate.TranslateElement({pageLanguage:'ja',includedLanguages:'en,fr,sv,zh-CN,ko,my,id,th',autoDisplay:false},'google_translate_element');}catch(e){translationLoader=null;}
}
function ensureTranslation(target){
 if(translationLoader)return translationLoader;
 translationLoader=new Promise((resolve,reject)=>{
  let elapsed=0,failed=false;
  const old=document.querySelector('script[data-translation-loader]');if(old)old.remove();
  const poll=()=>{
   const combo=document.querySelector('select.goog-te-combo');
   if(combo&&Array.from(combo.options).some(o=>o.value===target)){resolve(combo);return;}
   if(failed||(elapsed+=200)>12000){translationLoader=null;reject(new Error('translation unavailable'));return;}
   setTimeout(poll,200);
  };
  if(window.google&&google.translate){googleTranslateElementInit();}
  else{const loader=document.createElement('script');loader.dataset.translationLoader='true';loader.src='https://translate.google.com/translate_a/element.js?cb=googleTranslateElementInit';loader.async=true;loader.onerror=()=>{failed=true;};document.head.append(loader);}
  poll();
 });return translationLoader;
}
function selectTranslationLanguage(source){
 ++translationRequest;translationSelect.value=source.value;desktopTranslationSelect.value=source.value;
 setTranslationStatus(source.value==='ja'?'日本語に戻すには「翻訳する」を押してください。':languageNames[source.value]+'：翻訳するを押してください。');
}
translationSelect.addEventListener('change',()=>selectTranslationLanguage(translationSelect));
desktopTranslationSelect.addEventListener('change',()=>selectTranslationLanguage(desktopTranslationSelect));
let iphoneTranslationObserver=null,iphoneTranslationFinishTimer=null,iphoneTranslationMaxTimer=null;
function beginIphoneTranslationVisual(){
 if(!matchMedia('(max-width:980px)').matches)return;
 document.body.classList.add('iphone-translation-running');
 if(iphoneTranslationObserver)iphoneTranslationObserver.disconnect();
 clearTimeout(iphoneTranslationFinishTimer);clearTimeout(iphoneTranslationMaxTimer);
 const main=document.querySelector('main');if(!main)return;
 const finish=()=>{clearTimeout(iphoneTranslationFinishTimer);clearTimeout(iphoneTranslationMaxTimer);if(iphoneTranslationObserver)iphoneTranslationObserver.disconnect();iphoneTranslationObserver=null;document.body.classList.remove('iphone-translation-running');};
 iphoneTranslationObserver=new MutationObserver(()=>{clearTimeout(iphoneTranslationFinishTimer);iphoneTranslationFinishTimer=setTimeout(finish,650);});
 iphoneTranslationObserver.observe(main,{subtree:true,childList:true,characterData:true});
 iphoneTranslationFinishTimer=setTimeout(finish,1200);
 iphoneTranslationMaxTimer=setTimeout(finish,5500);
}
function finishIphoneTranslationVisual(){
 clearTimeout(iphoneTranslationFinishTimer);clearTimeout(iphoneTranslationMaxTimer);
 if(iphoneTranslationObserver)iphoneTranslationObserver.disconnect();iphoneTranslationObserver=null;
 document.body.classList.remove('iphone-translation-running');
}
async function openOnlineTranslation(){
 const lang=translationSelect.value,target=lang==='zh'?'zh-CN':lang,request=++translationRequest;
 rememberTranslationState(lang);
 if(lang==='ja'){
  clearGoogTransCookie();
  try{sessionStorage.removeItem('kazuTranslatePending');}catch(e){}
  if(appliedLanguage!=='ja'||document.documentElement.className.includes('translated')){location.reload();return;}
  applyInterfaceLanguage('ja');setTranslationStatus('日本語（原文）');finishIphoneTranslationVisual();return;
 }
 // v1.71: まず同じ画面内のGoogle翻訳を試す。iPhone/Safariで埋め込み翻訳が使えない場合は同じタブへフォールバックする。
 if(matchMedia('(max-width:980px)').matches){
  clearGoogTransCookie();
  setGoogTransCookie(target);
  try{sessionStorage.removeItem('kazuTranslatePending');}catch(e){}
 }
 beginIphoneTranslationVisual();
 applyInterfaceLanguage(lang);
 setTranslationStatus('翻訳を読み込んでいます…');
 try{
  const combo=await ensureTranslation(target);if(request!==translationRequest){finishIphoneTranslationVisual();return;}
  combo.value=target;combo.dispatchEvent(new Event('change',{bubbles:true}));appliedLanguage=lang;
  try{sessionStorage.removeItem('kazuTranslatePending');}catch(e){}
  setTranslationStatus(languageNames[lang]+'：翻訳しました。');
 }catch(e){
  if(request!==translationRequest){finishIphoneTranslationVisual();return;}
  finishIphoneTranslationVisual();
  // iPhone/SafariはGoogleの埋め込み翻訳が読み込めないことがある。
  // その場合も無反応にせず、同じタブでGoogle翻訳版の現在ページを開く。
  if(matchMedia('(max-width:980px)').matches){
   setTranslationStatus('iPhone用の翻訳へ切り替えます…');
   const translatedUrl='https://translate.google.com/translate?sl=ja&tl='+encodeURIComponent(target)+'&u='+encodeURIComponent(location.href);
   location.assign(translatedUrl);
   return;
  }
  setTranslationStatus('本文の翻訳サービスに接続できませんでした。「翻訳する」で再試行できます。');
 }
}
document.getElementById('onlineTranslateButton').addEventListener('click',openOnlineTranslation);
desktopTranslateButton.addEventListener('click',()=>{translationSelect.value=desktopTranslationSelect.value;openOnlineTranslation();});
document.getElementById('closeTranslationDialog').addEventListener('click',()=>document.getElementById('onlineTranslationDialog').close());
